parameters.functionCode:
// Normalizar datos de entrada
const body = items[0].json.body || items[0].json;

const data = {
  nombre: body.name || body.nombre || '',
  email: body.email || '',
  telefono: body.phone || body.telefono || '',
  fecha: body.date || body.fecha || '',
  hora: body.time || body.hora || '',
  timeSlot: body.timeSlot || 'afternoon',
  pax: parseInt(body.guests || body.pax || 20),
  duracion: body.duration || '4',
  extras: JSON.stringify(body.extras || []),
  tipoEvento: body.eventType || body.tipoEvento || 'cumpleanos',
  mensaje: (body.message || body.mensaje || '').replace(/'/g, "''"),
  precioBase: parseFloat(body.basePrice || 0),
  precioTotal: parseFloat(body.totalPrice || body.precioTotal || 0),
  depositoAmount: parseFloat(body.depositAmount || body.depositoAmount || 0),
  metodoPago: body.paymentMethod || 'cash'
};

// Calcular fechas para Calendar
const [year, month, day] = data.fecha.split('-');
const [hours, minutes] = data.hora.split(':');
const startDateTime = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), parseInt(hours), parseInt(minutes || '0'));
const durationHours = parseInt(data.duracion);
const endDateTime = new Date(startDateTime);
endDateTime.setHours(endDateTime.getHours() + durationHours);

return [{
  json: {
    ...data,
    fechaHoraInicio: startDateTime.toISOString(),
    fechaHoraFin: endDateTime.toISOString(),
    fechaFormateada: `${day}/${month}/${year}`,
    horaFormateada: `${hours}:${minutes || '00'}h`,
    timestamp: new Date().toISOString()
  }
}];

// Robust availability check - handle any Postgres output format
const pgResult = items[0].json;
let total = 0;

// Handle different possible formats from Postgres node
if (pgResult.total !== undefined) {
  total = parseInt(pgResult.total) || 0;
} else if (Array.isArray(pgResult) && pgResult[0]?.total !== undefined) {
  total = parseInt(pgResult[0].total) || 0;
} else if (pgResult.rows && pgResult.rows[0]?.total !== undefined) {
  total = parseInt(pgResult.rows[0].total) || 0;
}

// Get original data from NormalizarDatos
const data = $('NormalizarDatos').item.json;

return [{
  json: {
    ...data,
    isAvailable: total === 0,
    existingCount: total
  }
}];

