// Merge DB result (id) with original reservation data
const dbResult = items[0].json;
const data = $('VerificarYMerge').item.json;

// Handle different possible id formats from Postgres
let dbId = dbResult.id;
if (!dbId && Array.isArray(dbResult) && dbResult[0]) dbId = dbResult[0].id;
if (!dbId && dbResult.rows && dbResult.rows[0]) dbId = dbResult.rows[0].id;

return [{ json: { ...data, dbId: dbId || 0 } }];

