const data = $('MergeConDatos').item.json;
const calendarEvent = items[0].json;

const reservationId = `RES-${data.fecha.replace(/-/g, '')}-${String(data.dbId).padStart(3, '0')}`;

return [{
  json: {
    reservationId,
    nombre: data.nombre,
    email: data.email,
    telefono: data.telefono,
    fecha: data.fechaFormateada,
    hora: data.horaFormateada,
    pax: data.pax,
    tipoEvento: data.tipoEvento,
    extras: data.extras,
    metodoPago: data.metodoPago,
    total: data.precioTotal,
    deposito: data.depositoAmount,
    calendarEventId: calendarEvent.id || '',
    dbId: data.dbId
  }
}];

// Check if emails were sent successfully
const data = $('PrepararRespuesta').item.json;
const response = {
  success: true,
  reservationId: data.reservationId,
  message: 'Reserva creada exitosamente'
};

// Check GmailCliente for errors
try {
  const emailResult = $('GmailCliente').item.json;
  if (emailResult.error) {
    response.emailWarning = 'No se pudo enviar el email de confirmacion. Te contactaremos pronto.';
  }
} catch (e) {
  response.emailWarning = 'No se pudo enviar el email de confirmacion. Te contactaremos pronto.';
}

return [{ json: response }];
